$ErrorActionPreference = "Stop"

Write-Host "SlateLane Phase 029C - Dispatcher Utility Toolkit" -ForegroundColor Cyan

if (-not (Test-Path "package.json")) {
  throw "Run this script from the root of your slatelane-dispatch project (the folder containing package.json)."
}

$PagePath = "src/app/admin/tools/page.tsx"
$RoutePath = "src/app/api/admin/dispatcher-tools/preferences/route.ts"
$LayoutPath = "src/app/admin/layout.tsx"

New-Item -ItemType Directory -Force -Path (Split-Path $PagePath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $RoutePath) | Out-Null

$PageBase64 = @'

'@

$RouteBase64 = @'

'@

[System.IO.File]::WriteAllBytes($PagePath, [System.Convert]::FromBase64String($PageBase64.Trim()))
[System.IO.File]::WriteAllBytes($RoutePath, [System.Convert]::FromBase64String($RouteBase64.Trim()))

if (-not (Test-Path $LayoutPath)) {
  throw "Could not find $LayoutPath"
}

$Layout = Get-Content $LayoutPath -Raw

if ($Layout -notmatch '"/admin/tools"') {
  $Marker = @'
  {
    href:
      "/admin/import",
    label:
      "FMCSA Import",
  },
'@

  $ToolsItem = @'
  {
    href:
      "/admin/tools",
    label:
      "Dispatcher Tools",
    badge:
      "Tools",
  },

'@

  if (-not $Layout.Contains($Marker)) {
    throw "Could not find the FMCSA Import navigation block in layout.tsx. The two new files were created, but the sidebar was not changed."
  }

  $Layout = $Layout.Replace($Marker, $ToolsItem + $Marker)
  Set-Content -Path $LayoutPath -Value $Layout -NoNewline
}

Write-Host "Created: $PagePath" -ForegroundColor Green
Write-Host "Created: $RoutePath" -ForegroundColor Green
Write-Host "Updated: $LayoutPath" -ForegroundColor Green
Write-Host ""
Write-Host "Database migration is already live in Supabase. Running production build check..." -ForegroundColor Yellow

npm run build

if ($LASTEXITCODE -ne 0) {
  throw "Build failed. Copy the error output back into ChatGPT and I will fix it."
}

Write-Host ""
Write-Host "PHASE 029C BUILD SUCCESS" -ForegroundColor Green
Write-Host "Next: git add . ; git commit -m 'Add Phase 029C dispatcher utility toolkit' ; git push" -ForegroundColor Cyan
